dir:





























































































	---select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select @@fields into #t from vdmcangap a @@join
	  where a.ma_ttp like '%'+@ma_ttp+'%' and  a.ma_qg like '%'+@ma_qg+'%' and a.hk_yn = 1
	  order by ma_cang

	select * from #t order by ma_cang

	select @ma_ttp as ma_ttp , @ma_qg as ma_qg from vdmcangap a 
	  left join dmttp b on a.ma_ttp =b.ma_ttp left join dmquocgia c on a.ma_qg =c.ma_qg
	where a.ma_ttp like '%'+@ma_ttp+'%' and  a.ma_qg like '%'+@ma_qg+'%' and a.hk_yn = 1









  &DefaultButton;




function filter$s323C1Select(p){
  this.constructor(p);
}
filter$s323C1Select.prototype = new DirEvent();
filter$s323C1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$s323C1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct','chon_yn', 'ma_ttp', 'ten_ttp', 'ma_qg', 'ten_qg', 'unit_id'], [p.options._ngay_ct,p.options._chon_yn,p.options._ma_ttp, p.options._ten_ttp,p.options._ma_qg, p.options._ten_qg, p.options._unit_id]);
	//dir$s323C1SetMaster(p);

}

function dir$s323C1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$s323C1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	 // p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,  p.options._ma_nt, p.options._unit_id]);
    dt.removeRow('[chon_yn0] == 0');
    pa.appendGrid(1, dt, p.valForm('xprocess') == "2", '', '');
    //pa.calcExpressionAll(1, 'chon_yn');
    //pa.appendForm(master, 0);
    p._close();
	//pa.valForm([ma_noi_den],['ADDD']);
	// p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}
